import XCTest
@testable import Nolune

/// A profile's pages as the gateway serves them (ProfilePages.swift), from its own answers.
final class ProfilePagesTests: XCTestCase {
	private func decode<T: Decodable>(_ type: T.Type, _ json: String) throws -> T {
		try JSONDecoder().decode(type, from: Data(json.utf8))
	}

	func testMemory() throws {
		let memory = try decode(MemoryOverview.self, MEMORY)
		XCTAssertEqual(memory.files.map(\.path), ["core.md", "home.md", "people/leo.md"])
		XCTAssertEqual(memory.files[1].facts.count, 2)
		XCTAssertEqual(memory.cards.map(\.owner), ["Anna", "Max"])
		XCTAssertNil(memory.cards[0].file)
		XCTAssertEqual(memory.core.maxChars, 4000)
		XCTAssertTrue(memory.learnFromChats)
		XCTAssertEqual(MemoryCategory.title(of: memory.files[1]), "Home")
		XCTAssertEqual(MemoryCategory.title(of: memory.files[0]), "core")
	}

	func testWhereNotesBelong() {
		XCTAssertEqual(MemoryCategory.of("core.md"), .core)
		XCTAssertEqual(MemoryCategory.of("people/leo.md"), .people)
		XCTAssertEqual(MemoryCategory.of("projects/garden.md"), .projects)
		XCTAssertEqual(MemoryCategory.of("pets.md"), .pets)
		XCTAssertNil(MemoryCategory.of("recipes.md"))
		XCTAssertEqual(MemoryCategory.fileName("Anna Maria Ölz"), "anna-maria-olz")
	}

	func testAutomations() throws {
		let automations = try decode(AutomationsOverview.self, AUTOMATIONS)
		XCTAssertEqual(automations.triggers.map(\.name), ["Weather", "Dentist"])
		XCTAssertEqual(automations.triggers[0].schedule, "Every weekday at 07:30")
		XCTAssertEqual(automations.triggers[0].icon, "cloud-rain")
		XCTAssertEqual(automations.triggers[1].action, "script")
		XCTAssertEqual(automations.calendar.weekdays.count, 7)
		XCTAssertEqual(automations.calendar.cells.count % 7, 0)
		XCTAssertTrue(automations.calendar.cells.contains { !$0.entries.isEmpty })
	}

	func testSkills() throws {
		let skills = try decode(Skills.self, SKILLS).skills
		XCTAssertTrue(skills.contains { $0.name == "automations" && $0.scope == "builtin" && $0.enabled })
	}

	func testPeopleAndProfile() throws {
		let settings = try decode(ProfileSettings.self, SETTINGS)
		XCTAssertEqual(settings.members.map(\.name), ["Anna", "Max"])
		XCTAssertEqual(settings.members[0].note, "people/anna.md")
		XCTAssertEqual(settings.people.first?.facts, ["Likes trains."])
		XCTAssertEqual(settings.others, ["Leo"])
		let choose = try decode(MemberAdded.self, #"{"choose":{"who":"Leo","candidates":[{"path":"people/leo.md","title":"Leo","who":null,"aliases":[],"facts":[]}]}}"#)
		XCTAssertEqual(choose.choose?.candidates.map(\.path), ["people/leo.md"])
		XCTAssertNil(try decode(MemberAdded.self, #"{"message":"Added Leo."}"#).choose)
	}

	func testFolder() throws {
		let folder = try decode(FolderDetail.self, FOLDER)
		XCTAssertEqual(folder.name, "Trip to Japan")
		XCTAssertEqual(folder.maxFiles, 50)
	}

	func testPictures() throws {
		let images = try decode(ImagesOverview.self, IMAGES)
		XCTAssertFalse(images.ready)
		XCTAssertNotNil(images.problem)
		let invitation = try XCTUnwrap(images.templates.first { $0.id == "party-invitation" })
		XCTAssertEqual(invitation.settings.map(\.id), ["theme", "name", "age", "when", "where"])
		guard case .select(_, _, let theme, let options, let custom) = invitation.settings[0] else { return XCTFail("a select") }
		XCTAssertEqual(theme, "dinosaur")
		XCTAssertTrue(custom)
		XCTAssertEqual(options.first?.label, "dinosaur")
		XCTAssertTrue(images.templates.contains { $0.imageSource == "drawing" })
		XCTAssertTrue(images.templates.contains { $0.settings.contains { if case .emoji = $0 { return true } else { return false } } })

		XCTAssertEqual(
			invitation.sentence(with: ["theme": "outer-space", "name": "Leo", "age": "6"], picture: ""),
			"Make a outer space party invitation for Leo, turning 6."
		)
		XCTAssertEqual(
			invitation.sentence(with: ["theme": "pirate"], picture: "the photo"),
			"Make a pirate party invitation for name, starring the kid in the photo."
		)
	}
}

